WITH cleaned AS (SELECT id, email, dept_id, job_title, salary, hire_date, is_remote, FLOOR(salary) AS salary_whole, COALESCE(level, 'N/A') AS level_clean FROM employees WHERE LOWER(email) LIKE '%ran%') SELECT id, email, dept_id, job_title, hire_date, COUNT(salary_whole) OVER w_running AS last4_count_salary_whole, AVG(salary_whole) OVER w_running AS last4_avg_salary_whole, MAX(salary_whole) OVER w_running AS last4_max_salary_whole FROM cleaned WHERE salary <= 109000 WINDOW w_running AS (PARTITION BY job_title ORDER BY salary_whole, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)
